  "changeName": "cross-app-asset-references",
  "changeDir": "/Users/maparent/OpenSource/discourse-graph/openspec/changes/cross-app-asset-references",
  "schemaName": "spec-driven",
  "contextFiles": {
    "proposal": [
      "/Users/maparent/OpenSource/discourse-graph/openspec/changes/cross-app-asset-references/proposal.md"
    ],
    "specs": [
