    expect(asset.filename).toBe("CleanShot 2025-11-16 at 17.14.44@2x.png");
    expect(asset.mimetype).toBe("image/png");
    expect(new TextDecoder().decode(asset.content)).toBe("PNGDATA");
  });

  it("reports the size of the bytes it actually holds", async () => {
    mockFetch({ descriptor: descriptorWithName, bytes: "PNGDATA" });

    const asset = await fetchRoamAsset(ASSET_URL);

    expect(asset.size).toBe(7);
  });

  it("reads the descriptor before downloading", async () => {
    const { calls } = mockFetch({ descriptor: descriptorWithName });

    await fetchRoamAsset(ASSET_URL);

    expect(calls).toHaveLength(2);
    expect(calls[0]).not.toContain("alt=media");
    expect(calls[1]).toContain("alt=media");
  });

  it("throws when the bytes cannot be fetched", async () => {
    mockFetch({ descriptor: descriptorWithName, bytesStatus: 403 });

    await expect(fetchRoamAsset(ASSET_URL)).rejects.toThrow(
      /Could not fetch asset \(403\)/,
    );
  });
});

