1	/**
2	 * Fetches one asset from Roam's storage, along with the name it was uploaded under.
3	 *
4	 * Roam's storage URL carries a random uid rather than the original file name
5	 * (`imgs/app/<graph>/lqP2ioVNC3.png`), so the name has to be read separately. Firebase
6	 * keeps it in the object's custom metadata, and requesting the same URL with `alt=media`
7	 * removed returns the object descriptor as JSON instead of the bytes. That read is cheap,
8	 * needs no Roam API, and also yields the size, so a caller can decide whether an asset is
9	 * worth downloading before downloading it.
10	 */
11	
12	/** Where Roam records the uploaded name, alongside `file-type`. */
13	const UPLOADED_NAME_KEY = "file-name";
14	
15	type FirebaseObjectDescriptor = {
16	  /** The full object path, e.g. "imgs/app/MAPLab/lqP2ioVNC3.png". */
17	  name?: string;
18	  contentType?: string;
19	  /** Firebase reports the byte count as a string. */
20	  size?: string;
21	  timeCreated?: string;
22	  updated?: string;
23	  metadata?: Record<string, string>;
24	};
25	
26	export type RoamAssetDescriptor = {
27	  /** The name the file was uploaded under, or the storage uid when Roam kept none. */
28	  filename: string;
29	  mimetype: string;
30	  /** Byte count, or undefined when the descriptor did not report one. */
31	  size: number | undefined;
32	  /** When Roam's storage recorded the object, where it reports them. */
33	  createdAt: Date | undefined;
34	  modifiedAt: Date | undefined;
35	};
36	
37	export type RoamAsset = RoamAssetDescriptor & {
38	  content: ArrayBuffer;
39	};
40	
41	const DEFAULT_MIMETYPE = "application/octet-stream";
42	
43	/**
44	 * The same URL with `alt=media` removed, which returns the object descriptor rather than
45	 * the bytes. The download token is kept: it governs access to both.
46	 */
47	export const assetDescriptorUrl = (assetUrl: string): string => {
48	  const url = new URL(assetUrl);
49	  url.searchParams.delete("alt");
50	  return url.toString();
51	};
52	
53	/**
54	 * The storage uid, used as the name when Roam recorded none. This is what Roam's own
55	 * `file.get` falls back to, so an asset with no metadata gets the same name here as it
56	 * would there.
57	 */
58	const storageUidFromPath = (objectPath: string): string => {
59	  const segments = decodeURIComponent(objectPath).split("/");
60	  return segments[segments.length - 1] ?? "";
61	};
62	
63	const storageUidFromUrl = (assetUrl: string): string => {
64	  try {
65	    return storageUidFromPath(new URL(assetUrl).pathname);
66	  } catch {
67	    return "";
68	  }
69	};
70	
71	const parseTimestamp = (value: string | undefined): Date | undefined => {
72	  if (value === undefined) return undefined;
73	  const parsed = new Date(value);
74	  return Number.isNaN(parsed.valueOf()) ? undefined : parsed;
75	};
76	
77	const describeAsset = (
78	  descriptor: FirebaseObjectDescriptor,
79	  assetUrl: string,
80	): RoamAssetDescriptor => {
81	  const uploadedName = descriptor.metadata?.[UPLOADED_NAME_KEY];
82	  const fallbackName =
83	    descriptor.name !== undefined
84	      ? storageUidFromPath(descriptor.name)
85	      : storageUidFromUrl(assetUrl);
86	  const size = descriptor.size === undefined ? NaN : Number(descriptor.size);
87	  return {
88	    filename: uploadedName || fallbackName,
89	    mimetype: descriptor.contentType || DEFAULT_MIMETYPE,
90	    size: Number.isFinite(size) ? size : undefined,
91	    createdAt: parseTimestamp(descriptor.timeCreated),
92	    modifiedAt: parseTimestamp(descriptor.updated),
93	  };
94	};
95	
96	/**
97	 * Reads the object descriptor without transferring the file.
98	 *
99	 * Throws when the read fails. The publish stage catches per asset, so one unreadable
100	 * asset never fails its node.
101	 */
102	export const fetchAssetDescriptor = async (
103	  assetUrl: string,
104	): Promise<RoamAssetDescriptor> => {
105	  const response = await fetch(assetDescriptorUrl(assetUrl));
106	  if (!response.ok)
107	    throw new Error(
108	      `Could not read asset descriptor (${response.status}): ${assetUrl}`,
109	    );
110	  const descriptor = (await response.json()) as FirebaseObjectDescriptor;
111	  return describeAsset(descriptor, assetUrl);
112	};
113	
114	/** Downloads the bytes alone, for a caller that has already read the descriptor. */
115	export const fetchAssetBytes = async (
116	  assetUrl: string,
117	): Promise<ArrayBuffer> => {
118	  const response = await fetch(assetUrl);
119	  if (!response.ok)
120	    throw new Error(`Could not fetch asset (${response.status}): ${assetUrl}`);
121	  return response.arrayBuffer();
122	};
123	
124	/**
125	 * Reads the descriptor, then downloads the bytes.
126	 *
127	 * The descriptor comes first so the name and size are known before the transfer. A caller
128	 * that only needs to decide whether to copy an asset should call `fetchAssetDescriptor`
129	 * and stop there. Throws when either request fails.
130	 */
131	export const fetchRoamAsset = async (assetUrl: string): Promise<RoamAsset> => {
132	  const described = await fetchAssetDescriptor(assetUrl);
133	  const content = await fetchAssetBytes(assetUrl);
134	  return {
135	    ...described,
136	    // The descriptor's size is Roam's claim; the bytes we actually hold are the truth.
137	    size: content.byteLength,
